page Simulacion "/" {
  state count = 5
  state frames = 0
  state paused = false

  ref box
  ref balls
  ref raf

  fn makeBalls(n) {
    let list = []
    for (let i = 0; i < n; i++) {
      list.push(newBall())
    }
    return list
  }

  fn newBall() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: 10
    }
  }

  fn step() {
    if paused { return }
    let n = balls.length
    for (let i = 0; i < n; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
    }
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let dist = Math.hypot(dx, dy)
        let min = a.r + b.r
        if dist < min {
          let nx = 1
          let ny = 0
          if dist > 0 {
            nx = dx / dist
            ny = dy / dist
          }
          let push = (min - dist) / 2
          a.x -= nx * push
          a.y -= ny * push
          b.x += nx * push
          b.y += ny * push
          let dvn = (a.vx - b.vx) * nx + (a.vy - b.vy) * ny
          if dvn > 0 {
            a.vx -= dvn * nx
            a.vy -= dvn * ny
            b.vx += dvn * nx
            b.vy += dvn * ny
          }
        }
      }
    }
    for (let i = 0; i < n; i++) {
      let b = balls[i]
      if b.x < b.r {
        b.x = b.r
        b.vx = Math.abs(b.vx)
      }
      if b.x > 400 - b.r {
        b.x = 400 - b.r
        b.vx = -Math.abs(b.vx)
      }
      if b.y < b.r {
        b.y = b.r
        b.vy = Math.abs(b.vy)
      }
      if b.y > 300 - b.r {
        b.y = 300 - b.r
        b.vy = -Math.abs(b.vy)
      }
    }
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for (let i = 0; i < n; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
    frames++
    raf = requestAnimationFrame(step)
  }

  fn add() {
    balls.push(newBall())
    count = balls.length
  }

  fn togglePause() {
    if paused {
      paused = false
      cancelAnimationFrame(raf)
      raf = requestAnimationFrame(step)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn restart() {
    balls = makeBalls(5)
    count = 5
    frames = 0
    if !paused {
      cancelAnimationFrame(raf)
      raf = requestAnimationFrame(step)
    }
  }

  mount {
    balls = makeBalls(5)
    raf = requestAnimationFrame(step)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> togglePause()
      button "Reiniciar" danger -> restart()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

page Sim "/" {
  ref box
  ref balls
  ref raf

  state n = 5
  state frames = 0
  state paused = false

  computed label = paused ? "Reanudar" : "Pausar"

  fn rnd(a, b) {
    return a + Math.random() * (b - a)
  }

  fn makeBall() {
    return { x: rnd(10, 390), y: rnd(10, 290), vx: rnd(-3, 3), vy: rnd(-3, 3) }
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#e11d48"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, 10, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d2 = dx * dx + dy * dy
        if d2 < 400 {
          let d = Math.sqrt(d2)
          if d < 0.01 {
            dx = 1
            dy = 0
            d = 1
          }
          let nx = dx / d
          let ny = dy / d
          let overlap = 20 - d
          a.x -= nx * overlap / 2
          a.y -= ny * overlap / 2
          c.x += nx * overlap / 2
          c.y += ny * overlap / 2
          let tvx = a.vx
          let tvy = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tvx
          c.vy = tvy
        }
      }
    }
    for b in balls {
      if b.x < 10 {
        b.x = 10
        b.vx = -b.vx
      }
      if b.x > 390 {
        b.x = 390
        b.vx = -b.vx
      }
      if b.y < 10 {
        b.y = 10
        b.vy = -b.vy
      }
      if b.y > 290 {
        b.y = 290
        b.vy = -b.vy
      }
    }
  }

  fn tick() {
    step()
    draw()
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(makeBall())
    }
    n = 5
    frames = 0
  }

  fn add() {
    balls.push(makeBall())
    n = balls.length
    if paused { draw() }
  }

  fn toggle() {
    paused = !paused
    if paused {
      cancelAnimationFrame(raf)
    } else {
      raf = requestAnimationFrame(tick)
    }
  }

  fn restart() {
    reset()
    draw()
  }

  mount {
    reset()
    draw()
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button label -> toggle()
      button "Reiniciar" -> restart()
    }
    text `Pelotas: ${n}`
    text `Cuadros: ${frames}`
  }
}
